import csv,re
S='/projectnb/jbrcs/mangband/github/src/server/'
inp=list(csv.DictReader(open('/projectnb/jbrcs/mangband/Advisor/studies/2026-09-29-messages/scratch/M2_input.csv')))
byid={x['id']:x for x in inp}
rows=[]
PH={'<monster>':('mon','.+?','Grip'),'<Monster>':('mon','.+?','Grip'),'<item>':('item','.+?','Dagger'),'<n>':('n',r'\d+','5'),
    '<name>':('name','.+?','Bob'),'<killer>':('killer','.+?','Grip'),'<lbl>':('lbl','.','a'),'<x>':('x','.+?','foo'),'<note>':('note','.+?','dies.')}
def mk(text,regex=None):
    if regex: return regex,None
    r=re.escape(text); s=text
    for k,(g,pat,samp) in PH.items():
        ek=re.escape(k)
        if ek in r:
            r=r.replace(ek,'(?P<%s>%s)'%(g,pat),1)
            s=s.replace(k,samp,1)
    return '^'+r.replace(r'\ ',' ')+'$',s
def R(i,text,event,aud,rel,cond,notes='',regex=None,sample=None):
    i=str(i); x=byid[i]
    rg,s=mk(text,regex)
    rows.append(dict(id=i,file=x['file'],line=x['line'],text=text,event=event,audience=aud,pilot_relevance=rel,regex=rg,condition=cond,notes=notes,_s=sample if sample else s))
def gf(line):
    L=open(S+'spells1.c').read().split('\n')
    for k in range(line-1,0,-1):
        m=re.search(r'case (GF_\w+):',L[k])
        if m: return m.group(1)
