# ---- write + check
order={x['id']:k for k,x in enumerate(inp)}
missing=[x['id'] for x in inp if x['id'] not in {r['id'] for r in rows}]
print('missing',missing)
bad=0
for r in rows:
    c=re.compile(r['regex'])
    s=r['_s']
    if s is None: continue
    if r['regex']==r'^(?!)$': continue
    if not c.match(s): print('NOMATCH',r['id'],r['regex'],'|',s); bad+=1
rows.sort(key=lambda r:order[r['id']])
cols=['id','file','line','text','event','audience','pilot_relevance','regex','condition','notes']
with open('/projectnb/jbrcs/mangband/Advisor/studies/2026-09-29-messages/scratch/M2_catalogue.csv','w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=cols,extrasaction='ignore'); w.writeheader(); w.writerows(rows)
print(len(rows),'rows; bad',bad)
